import { Button, ClickableTile, Tag } from '@carbon/react'
import { ArrowRight } from '@carbon/react/icons/index.js'
import PropTypes from 'prop-types'
import React, { useCallback } from 'react'

export const ListPanelItem = ({
  name,
  desc,
  categories,
  tags,
  handleLinkClick,
  startTutorial
}) => {
  const handleKeyDown = useCallback(evt => {
    if (
      evt.altKey === false &&
      evt.ctrlKey === false &&
      evt.metaKey === false &&
      evt.shiftKey === false &&
      (evt.key === 'Enter' || evt.key === ' ')
    ) {
      handleLinkClick()
    }
  }, [handleLinkClick])

  return (
    <li>
      <ClickableTile
        onClick={handleLinkClick}
        onKeyDown={handleKeyDown}
        tabIndex='0'
        className='list-panel-item'
      >
        <h2 className='list-panel-item__title'>
          {name}
        </h2>
        <p className='list-panel-item__text'>
          {desc}
        </p>
        <div className='list-panel-item__lower'>
          <div className='list-panel-item__lower-left'>
            {tags && tags.map(tag =>
              <Tag key={tag}>{tag}</Tag>
            )}
          </div>
          <div className='list-panel-item__categories-right'>
            {categories && categories.map(cat =>
              <Tag key={cat}>{cat}</Tag>
            )}
          </div>
          {startTutorial && (
            <Button
              kind='ghost'
              iconDescription='Start tutorial'
              renderIcon={ArrowRight}
              size='sm'
              onClick={startTutorial}
              className='list-panel-item__start-button'
            >
              Start
            </Button>
          )}
        </div>
      </ClickableTile>
    </li>
  )
}

ListPanelItem.propTypes = {
  name: PropTypes.node,
  desc: PropTypes.node,
  categories: PropTypes.arrayOf(PropTypes.string),
  tags: PropTypes.arrayOf(PropTypes.string),
  handleLinkClick: PropTypes.func,
  startTutorial: PropTypes.func
}
