/*
This javascript file is for the main patterns page which lists all the patterns and has promoted tutoroials at the top of the page.
The search capability is also in this file. It uses IdeFilter.
*/

import PropTypes from 'prop-types'
import React, { useState, useEffect, useCallback } from 'react'
import { useLocation, useNavigate } from 'react-router'

import repoMetadata from '../../../patterns_repo_metadata.json'
import { PATTERNS_REPO_METADATA_URL, fetchItemsForVersion } from '../../../utils/misc.js'
import { ListPanelItem } from '../../ListPanelItem/ListPanelItem.jsx'
import SideFilterPanel from '../../SideFilterPanel/SideFilterPanel.jsx'
import { IdeFilter } from '../../cdai/IdeFilter/IdeFilter.jsx'
import { IdePage } from '../../cdai/IdePage/IdePage.jsx'

const PatternsListItems = ({ search, filter, handleClick, patternsData }) => {
  const patterns = (patternsData && patternsData.categories[0].patterns) || repoMetadata.categories[0].patterns.slice()

  const v13Patterns = fetchItemsForVersion(patterns)

  // Do the positive search
  const searchRegex = new RegExp(search, 'i')
  const searchFunc = item =>
    searchRegex.exec(item.name) !== null ||
    searchRegex.exec(item.shortDesc) !== null ||
    searchRegex.exec(item.tags) !== null ||
    searchRegex.exec(item.category) !== null

  const searchedList = v13Patterns.filter(searchFunc)

  // Now do the filtering
  const filterFunc = item => {
    let keepPattern = true
    filter.categorys.forEach(filterCat => {
      if (item.category.includes(filterCat)) keepPattern = false
    })
    filter.tags.forEach(filterTag => {
      if (item.tags.includes(filterTag)) keepPattern = false
    })
    return keepPattern
  }
  const filteredList = searchedList.filter(filterFunc)

  const listDom = []
  for (const item of filteredList) {
    const _tags = (item.tags && item.tags.split(';')) || []
    const _categories = (item.category && item.category.split(',')) || []

    listDom.push(
      <ListPanelItem
        name={item.name}
        desc={item.shortDesc}
        categories={_categories}
        tags={_tags}
        key={item.name}
        handleLinkClick={() => handleClick(item.detailsURL, false)}
        patternData={item}
      />
    )
  }

  return (
    <ul className='patterns-list-items'>
      {listDom}
    </ul>
  )
}

PatternsListItems.propTypes = {
  search: PropTypes.string.isRequired,
  filter: PropTypes.shape({
    categorys: PropTypes.arrayOf(PropTypes.string).isRequired,
    tags: PropTypes.arrayOf(PropTypes.string).isRequired
  }),
  handleClick: PropTypes.func.isRequired,
  patternsData: PropTypes.any
}

const v13Patterns = fetchItemsForVersion(repoMetadata.categories[0].patterns)
const colours = [
  'red',
  'magenta',
  'purple',
  'blue',
  'cyan',
  'teal',
  'green',
  'gray',
  'cool-gray',
  'warm-gray'
]
const allTags = new Set()
const allCats = new Set()

for (const item of v13Patterns) {
  const tags = (item.tags && item.tags.split(';')) || []
  const categories = (item.category && item.category.split(',')) || []

  for (const tag of tags) {
    allTags.add(tag)
  }

  for (const cat of categories) {
    allCats.add(cat)
  }
}

// This is mutable??
const allCatOptions = [...allCats].map(cat => ({
  type: colours[Math.floor(Math.random() * colours.length)],
  value: cat,
  label: cat,
  selected: false
}))

const searchTagOptions = [{
  label: 'Tag',
  options: [...allTags].map(tag => ({
    type: colours[Math.floor(Math.random() * colours.length)],
    value: tag,
    label: tag,
    selected: false
  }))
}]

// Initially we want the filters to be shown NOT selected, yet ALL patterns should be displayed
// So here we initialise a set of filters which includes ALL categories, even though the UX has them unselected to start with.
const buildInitialFiltersQuery = () => ({
  categorys: allCatOptions.filter(item => item.selected).map(item => item.value),
  tags: []
})

function buildFiltersQuery () {
  // Rebuild the categories filter
  const filterQuerys = {
    categorys: allCatOptions.filter(item => !item.selected).map(item => item.value),
    tags: []
  }
  if (filterQuerys.categorys.length === 5) {
    return buildInitialFiltersQuery()
  }
  return filterQuerys
}

export const PatternsPage = () => {
  const location = useLocation()
  const navigate = useNavigate()
  const [searchQ, setSearchQ] = useState('')
  const [filterQ, setFilterQ] = useState(buildInitialFiltersQuery())

  // This causes the overview of the pattern to be shown.
  const handlePatternClick = useCallback(patternDetails => {
    navigate(`/${patternDetails}${location.search}`)
  }, [navigate, location])

  const handleSearchChange = val => {
    if (val) {
      const valMap = val.map(item => item.value)
      setSearchQ(`((${valMap.join(')|(')}))`)
    } else {
      setSearchQ('')
    }
  }

  const handleFilterChange = (itemName, itemIndex) => {
    // A category filter option has been either selected or unselected
    const filterToUpdate = allCatOptions[itemIndex]
    filterToUpdate.selected = !filterToUpdate.selected
    setFilterQ(buildFiltersQuery())
  }

  const handleResetFilters = () => {
    // Reset the category filter options back to NOT selected
    allCatOptions.forEach(tag => {
      tag.selected = false
    })
    setFilterQ(buildInitialFiltersQuery())
  }

  // Fetches latest repo_metadata from public GitHub
  const [patternsData, setPatternsData] = useState(null)
  useEffect(() => {
    // eslint-disable-next-line no-unused-vars
    const fetchPatternsData = async () => {
      const response = await fetch(PATTERNS_REPO_METADATA_URL, {
        headers: new Headers({
          Accept: 'application/vnd.github.v3+json'
        }),
        method: 'GET',
        mode: 'cors',
        credentials: 'omit' // Useful for including session ID (and, IIRC, authorization headers)
      })

      const responseData = await response.json()
      if (responseData) {
        setPatternsData(responseData)
      }
    }
    // Uncomment next line if you want to use a local dev version of repo_metadata.json
    // fetchPatternsData()
  }, [])

  return (
    <IdePage heading='Patterns'>
      <div className='patterns'>
        <IdeFilter
          options={searchTagOptions}
          onChange={handleSearchChange}
        />
        <div className='pattern-filter-content-layout__container'>
          <SideFilterPanel
            filterCats={allCatOptions}
            onCheckBoxChange={handleFilterChange}
            handleResetFilters={handleResetFilters}
          />
          <PatternsListItems
            search={searchQ}
            filter={filterQ}
            handleClick={handlePatternClick}
            patternsData={patternsData}
          />
        </div>
      </div>
    </IdePage>
  )
}
