const CATEGORY_SINGULARS = {
  FormatTransformation: 'Format Transformation Pattern',
  ProtocolTransformation: 'Protocol Transformation Pattern'
}

const PATTERN_OBJS = patternsRepoMetadata
  .categories
  .find(category => category.name === 'Tool Capabilities')
  .patterns

export const TransformationPatternPage = () => {
  const match = useMatch('/patterns/:category/:pattern')
  const patternObj = PATTERN_OBJS.find(pattern => match.pathname === `/${pattern.detailsURL}`)

  if (!patternObj) {
    // TODO: a 404?
    return null
  }

  const category = match.params.category
  const patternName = match.params.pattern

  const categorySingular = CATEGORY_SINGULARS[category]

  const idePageHeading = `${categorySingular}: ${patternObj.name.replace(/ Pattern$/, '')}`

  const flowPicture = PATTERN_FLOW_PICTURES[category][patternName]

  const handleClickStart = () => startPattern(
    patternObj.zipURL,
    `com.ibm.dev.pattern.${patternName}`,
    patternObj.pluginVersion || '1.0.0.0',
    `com.ibm.dev.pattern.${patternName}.Feature`
  )

  return (
    <IdePage heading={idePageHeading}>
      <div className='transformation-pattern-page'>
        <Link href='#/./patterns'>
          Back to the Patterns Gallery
        </Link>
        {flowPicture && (
          <img
            src={flowPicture}
            className='transformation-pattern-page__picture'
            alt=''
          />
        )}
        <p>{patternObj.shortDesc}</p>
        <Button
          size='sm'
          onClick={handleClickStart}
        >
          Start
        </Button>
      </div>
    </IdePage>
  )
}

TransformationPatternPage.propTypes = {}
