import { Button, Checkbox } from '@carbon/react'
import PropTypes from 'prop-types'
import React from 'react'

function SideFilterPanel ({ filterCats, onCheckBoxChange, handleResetFilters }) {
  return (
    <div className='side-filter-panel'>
      <Button kind='ghost' onClick={handleResetFilters}>
        Reset filters
      </Button>
      <div>
        <div className='side-filter-panel__headings'>
          Categories
        </div>
        {filterCats.map((cat, index) => (
          <div key={index}>
            <Checkbox
              id={`${cat.label}-tagid`}
              labelText={`${cat.label}`}
              value={cat.label}
              checked={cat.selected}
              disabled={false}
              onChange={() => onCheckBoxChange(cat.label, index)}
            />
          </div>
        ))}
      </div>
    </div>
  )
}

SideFilterPanel.propTypes = {
  filterCats: PropTypes.arrayOf(PropTypes.object),
  onCheckBoxChange: PropTypes.func.isRequired,
  handleResetFilters: PropTypes.func.isRequired
}

export default SideFilterPanel
